__NUXT_JSONP__("/finanzas-publicas/noticias/capacidad_de_pago_de_la_deuda_de_mexico_se_ha_deteriorado_en_los_ultimos_anos_ethos", (function(a,b,c,d){return {data:[{post:{slug:"capacidad_de_pago_de_la_deuda_de_mexico_se_ha_deteriorado_en_los_ultimos_anos_ethos",title:"“Capacidad de pago de la deuda de México se ha deteriorado en los últimos años”: Ethos",date:"2025-07-24T16:41:47.483Z",img:"https:\u002F\u002Fucarecdn.com\u002F0d87b49a-69b8-4bbc-a422-3e4abd3f5280\u002F","img-alt":"Deuda pública",autor:"Belén Saldívar, El Economista",link:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Feconomia\u002Fcapacidad-pago-deuda-mexico-deteriorado-ultimos-anos-20250723-769547.html",category:"finanzas-publicas",extracto:"El gobierno espera ingresos públicos por 8.05 billones de pesos, un crecimiento de 5.4%, en tanto, el SHRFSP creció 6.2 por ciento.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"La capacidad de pago de la deuda que tiene el gobierno mexicano se ha deteriorado en los últimos años, ante un mayor crecimiento del endeudamiento en comparación con los ingresos, señaló la organización Ethos Innovación en Políticas Públicas."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En un análisis sobre la situación de la deuda, la organización civil señaló que el endeudamiento – medido a través de los Requerimientos Financieros del Sector Público - representa cada vez una mayor proporción de los ingresos públicos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“En el 2016, el endeudamiento representó 17.1% de los ingresos, y fue a la baja hacia el 2018, cuando llegó a 10.1% de éstos. A partir del siguiente año, este porcentaje fue aumentando hasta alcanzar su punto máximo en el 2024, con 25.9%”, indicó el análisis."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El año pasado, la administración de Andrés Manuel López Obrador incurrió en un endeudamiento histórico, con el fin de poder terminar sus obras insignia, tales como el Tren Maya y la Refinería de Dos Bocas."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"De esta manera, el déficit fiscal llegó a un nivel de 5.7% del Producto Interno Bruto (PIB), mismo que se busca disminuir este año a 3.9 por ciento. De esta manera, se esperaría que el endeudamiento, como proporción de los ingresos, disminuya a 17.7 por ciento."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"No obstante, destacó que la drástica caída en la cifra de los RFSP como porcentaje de los ingresos no sería por un aumento en estos últimos, sino más bien por los recortes al gasto público que se han realizado en busca de la consolidación fiscal."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“En cuanto al saldo de la deuda, este duplica el tamaño de los ingresos presupuestarios. En promedio, durante los últimos 10 años, el saldo de la deuda ha sido 2.2 veces mayor que los ingresos públicos anuales. Esto indica que, incluso si el gobierno destinara todos sus ingresos presupuestarios a pagar la deuda, tardaría más de dos años en liquidar”, añadió."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En este sentido, señaló que este año la relación del saldo de la deuda respecto a los ingresos presupuestarios se mantendrá en 2.3 por ciento."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"De acuerdo con lo aprobado para este año, el gobierno espera ingresos públicos por 8.05 billones de pesos, un crecimiento de 5.4% respecto a lo aprobado. En tanto, el Saldo Histórico de los RFSP – la deuda en su medida más amplia – se aprobó en 51.4% del PIB, es decir, 18.6 billones de pesos, lo que representa un crecimiento de 6.2% en comparación con lo aprobado el año pasado."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:b,tag:"strong",props:{},children:[{type:a,value:"Sin respeto a la regla de oro"}]}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Ethos recordó que, de acuerdo con el artículo 73 de la Constitución Mexicana, existe una “regla de oro” de las finanzas públicas, en donde la inversión física debe ser igual o mayor que el endeudamiento para un año, el cual debe destinarse a obras que, directamente, produzcan un incremento en los ingresos públicos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Sin embargo, en los últimos 10 años esto no se ha respetado, dado que el endeudamiento ha sido mayor que el gasto en inversión física."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“En promedio, el endeudamiento ha sido 1.4 veces más grande que la inversión física. Esta regla se cumplió únicamente en el 2018, pues la inversión fue mayor al endeudamiento en 10 por ciento. Sin embargo, a partir del 2019 el endeudamiento ha sido mayor a la inversión”, explicó."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El año pasado, agregó, el endeudamiento fue casi el doble del gasto en inversión física, mientras que para este año se espera que el endeudamiento baje y sea 1.7 veces mayor, pero esto se daría por un menor endeudamiento y no una mayor inversión."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“El gasto en inversión para el 2025 se redujo 20.4% en términos reales, comparado con el 2024, siendo la caída más fuerte desde el 2017. Estos recortes en la inversión pueden causar pérdidas en la producción del país y deteriorar las perspectivas de crecimiento en el largo plazo”, aseveró."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Fcapacidad_de_pago_de_la_deuda_de_mexico_se_ha_deteriorado_en_los_ultimos_anos_ethos",extension:".md",createdAt:"2025-11-25T01:24:03.261Z",updatedAt:"2025-11-25T01:24:03.262Z"}}],fetch:{},mutations:[]}}("text","element","p","\n")));